  { Category = "Theme 10000"; Filename = "AR6.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR6.jpg"; Caption = "“The Crisis in Constantinople: A Group of Wounded Armenians in the Hospital” THE GRAPHIC, 26 Oct. 1895, p. 514. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.6)" }
  { Category = "Theme 10000"; Filename = "AR7.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR7.jpg"; Caption = "“The Crisis n Constantinople: Wounded Armenian Women in the Hospital. (Left:) A girl of fourteen, whose parents were killed, and who was herself badly beaten, (Center:) A woman, with a bayonet wound through the lung, who cannot live, (Right:) A woman suffering from cuts on her head and legs and from bruises”. THE GRAPHIC, 26 Oct. 1895, p. 514. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.7)" }
  { Category = "Theme 10000"; Filename = "AR10.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR10.jpg"; Caption = "Two workers of the Assistance Association accompanying three local workers in the burying of the highly decayed corpse of an Armenian victim of the Cilician massacre.1909. Archive of the German Assistance  Association for Christian Charity Work in  the Orient. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.10)" }
  { Category = "Theme 10000"; Filename = "AR11.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR11.jpg"; Caption = "An Armenian victim of the Cilician massacre.1909 Archive of the German  Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.11)" }
  { Category = "Theme 10000"; Filename = "AR12.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR12.jpg"; Caption = "An Armenian woman from Adana, having been tortured and maimed by knife wounds. This picture was taken by the German turkophile journalist Ernst Jaeckh, who propagated the official Turkish version which blamed the Cilician Armenian massacre on the conservative opposition to the Young Turks, in particular the Kurds, who were still loyal to the sultan.1909. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.12)" }
  { Category = "Theme 10000"; Filename = "AR13.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR13.jpg"; Caption = "Armenian children from Adana, from whose bodies pieces of flesh were ripped off with cotton hooks and whose kneekaps were severed.1909. Ernst Jaeckh, DER AUFSTEIGENDE HALBMOND. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.13)" }
  { Category = "Theme 10000"; Filename = "AR14.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR14.jpg"; Caption = "The Armenian quarter of Adana, razed and plundered. 1909 Ernst Jaeckh, DER AUFSTEIGENDE HALBMOND. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.14)" }
