  { Category = "Theme 10000"; Filename = "AR16.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR16.jpg"; Caption = "Adana: Ruins and robbed safes in the Armenian quarter.1909. Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.16)" }
  { Category = "Theme 10000"; Filename = "AR17.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR17.jpg"; Caption = "The ruins of Tarsus (Cilicia), 1909 Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.17)" }
  { Category = "Theme 10000"; Filename = "AR18.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR18.jpg"; Caption = "After the massacre: Armenian widows and orphans in Tarsus.1909 Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.18)" }
  { Category = "Theme 10000"; Filename = "AR19.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR19.jpg"; Caption = "Over three thousand Armenian refugees sought refuge with the Protestant church in Bakhche (Cilicia).1909. Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.19)" }
  { Category = "Theme 10000"; Filename = "AR20.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR20.jpg"; Caption = "The ruins of Haruniye after the massacre of April 1909 Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.20)" }
  { Category = "Theme 10000"; Filename = "AR21.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR21.jpg"; Caption = "Armenian victims of a typhus epidemic in Kishiftly (Cilicia) as a result of the massacre of April 1909 Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.21)" }
  { Category = "Theme 10000"; Filename = "AR22.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR22.jpg"; Caption = "The German Assistance Association in Haruniye distributing bedding and mess tins to needy Armenians.1909. Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.22)" }
  { Category = "Theme 10000"; Filename = "AR23.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR23.jpg"; Caption = "1909\nThe mission station at Haruniye distributing threshing plows to surviving Armenian farmers. Archive of the German Assistance Association. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.23)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR24.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR24.jpg"; Caption = "“The Shaikh-ul-Islam, the spiritual leader of all Sunni Muslims, announcing on 14 November 1914 before the Fathi Mosque in Constantinople the Jihad (holy war) against the ‘infidels’ and enemies of the faith” [whereby he meant primarily inland Christians as well as the Entente states]. DIE GESCHICHTE DES ERSTEN WELTKRIEGES, Bd. 1. (Stuttgart, Berlin, Leipzig: Union Deutsche Verlagsgesellschaft, n.d.), p.289. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.24)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR25.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR25.jpg"; Caption = "Muslim demonstration in Constantinople on the occasion of the call to holy war (November 14, 1914) BILDER IM SPIEGEL DER ZEIT. Bd. 3. (Zurich, 1971). (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.25)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR26.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR26.jpg"; Caption = "Armenians drafted into military service in the Ottoman army were not armed; rather, they had to perform labor, build streets or transport heavy loads. Most of those who did not die of malnutrition, exhaustion, or epidemic disease were murdered upon completion of their tasks. From the archive of Near East Relief in Maria Jacobsen, DIARY 1907-1919, KHARPUT, TURKEY (Beirut, 1979), p. 93. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.26)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR27.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR27.jpg"; Caption = "Soldiers of the Czarist army before an open mass grave with the corpses of murdered Armenian “Worker-soldiers” (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.27)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR28.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR28.jpg"; Caption = "The Armenian elite of the city of Kharberd (Kharpert, Harpoot) being led away under armed guard in May, 1915. The “deportation” of the Armenian civilian population began in 1915 with the murder of the intellectual, political, and religious elite. Often the local elite was led out of the city in order to be massacred at the nearest suitable site. Jacobsen, DIARY 1907-1919, KHARPUT, TURKEY. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.28)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR29.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR29.jpg"; Caption = "“The Turkish hangmen and the Armenian victim whose battered face was hidden from view” Armenian Historical research Association, ed., THE TURKISH ARMENOCIDE: THE GENOCIDE OF THE \nARMENIANS BY THE TURK, 2d ed. (Newton Square., 1965). (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.29)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR30.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR30.jpg"; Caption = "“Corpses of two Armenians tortured to death, prostrated on ladders and exhibited” From the Armin T. Wegner collection in  Aage Meyer Benedictsen, ARMENIEN ET  FOLKS LIV OG KAMP GENNEM TO  AARTUSINDER. MED KORT OG BILLEDER  (Copenhagen: Danske Armeniervenner, 1925). The photograph has obviously vanished, since it is not part of Wegner’s estate at Marbach. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.30)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR31.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR31.jpg"; Caption = "Armenian beaten to death Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.31)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR34.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR34.jpg"; Caption = "Armenian women and children on their death march. While a large proportion of Armenian men had already been murdered before the “deportations” began, a slow death by hunger, exhaustion, and disease awaited the women, children, and elderly. The woman were repeatedly plundered in transit and had to carry by themselves their entire possessions as well as their small children, since the farther south they went, the less money they had to rent wagons or beasts of burden. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.34)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR35.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR35.jpg"; Caption = "Armenian women and children on their death march. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.35)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR36.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR36.jpg"; Caption = "Armenian women and children on their death march. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.36)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR39.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR39.jpg"; Caption = "Erzurum was an important stop-off point for the deportees from the northeast of the Ottoman Empire. The German vice-consul Erwin von Scheubner-Richter photographed the “Camp of exiled Armenians” as well as the “Distribution of bread by consulate officials” (Scheubner-Richter’s captions). His nine photographs, unfortunately of poor quality, are located in the Political Archive of the Foreign Office in Bonn. However, the majority of deported Armenians never reached the “deportation goal” in Mesopotamia, despite this and other attempts to help them. Parts of the Islamic population and also the guards perpetrated too many massacres, and the strains of the forced marches were too great. Politisches Archiv des Auswartigen Amtes, Bonn, Turkei Archivbestand Botschaft Konstantinopel, Nr.  169. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.39)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR42.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR42.jpg"; Caption = "Stop of a deportation convoy in a city Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.42)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR43.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR43.jpg"; Caption = "The north Syria city of Aleppo was the main transition town for deportation convoys coming from Western Armenia, Central Anatolia, and Cilicia. There was also a German high school as well as a German consulate in Aleppo. The teacher, Dr. Martin Niepage, reported to the German parliament on October 15, 1915, the atrocities, taking place across from the school in a dilapidated caravan  seraglio. An expanded version appeared in 1916 as an independent publication, but was immediately confiscated by Saxon military officials. Niepage reported that weakened Armenians were wasting away and dying in filth in the courtyard of the seraglio, through hunger, typhus, and dysentery. The hygienic conditions were inconceivably poor. The German consul to Mosul, Hoffmann, representing Consul Rossler of Aleppo at that time, photographed the atrocious scenes and sent the pictures together with Niepage’s report to the foreign office in Bonn. Three of them are still located today in the political archive there. Niepage referred to the photographs taken by Hoffmann in the 1916 edition of his report: “They showed piles of corpses, amongst which still living children crawled or heeded the call of nature”. (Martin Niepage, Ein Wort an die berufenen Vertreter des Deutschen Volkes: Eindrucke eines deutschen Oberlehrers in der Turkei, p. 6.). Politisches Archiv des Auswartigen Amtes, Bonn, Turkei 183, Armenien, Bd.41. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.43)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR44.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR44.jpg"; Caption = "The north Syria city of Aleppo was the main transition town for deportation convoys coming from Western Armenia, Central Anatolia, and Cilicia. There was also a German high school as well as a German consulate in Aleppo. The teacher, Dr. Martin Niepage, reported to the German parliament on October 15, 1915, the atrocities, taking place across from the school in a dilapidated caravan  seraglio. An expanded version appeared in 1916 as an independent publication, but was immediately confiscated by Saxon military officials. Niepage reported that weakened Armenians were wasting away and dying in filth in the courtyard of the seraglio, through hunger, typhus, and dysentery. The hygienic conditions were inconceivably poor. The German consul to Mosul, Hoffmann, representing Consul Rossler of Aleppo at that time, photographed the atrocious scenes and sent the pictures together with Niepage’s report to the foreign office in Bonn. Three of them are still located today in the political archive there. Niepage referred to the photographs taken by Hoffmann in the 1916 edition of his report: “They showed piles of corpses, amongst which still living children crawled or heeded the call of nature”. (Martin Niepage, Ein Wort an die berufenen Vertreter des Deutschen Volkes: Eindrucke eines deutschen Oberlehrers in der Turkei, p. 6.). Politisches Archiv des Auswartigen Amtes,  Bonn, Turkei 183, Armenien, Bd. 41. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.44)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR45.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR45.jpg"; Caption = "The north Syria city of Aleppo was the main transition town for deportation convoys coming from Western Armenia, Central Anatolia, and Cilicia. There was also a German high school as well as a German consulate in Aleppo. The teacher, Dr. Martin Niepage, reported to the German parliament on October 15, 1915, the atrocities, taking place across from the school in a dilapidated caravan  seraglio. An expanded version appeared in 1916 as an independent publication, but was immediately confiscated by Saxon military officials. Niepage reported that weakened Armenians were wasting away and dying in filth in the courtyard of the seraglio, through hunger, typhus, and dysentery. The hygienic conditions were inconceivably poor. The German consul to Mosul, Hoffmann, representing Consul Rossler of Aleppo at that time, photographed the atrocious scenes and sent the pictures together with Niepage’s report to the foreign office in Bonn. Three of them are still located today in the political archive there. Niepage referred to the photographs taken by Hoffmann in the 1916 edition of his report: “They showed piles of corpses, amongst which still living children crawled or heeded the call of nature”. (Martin Niepage, Ein Wort an die berufenen Vertreter des Deutschen Volkes: Eindrucke eines deutschen Oberlehrers in der Turkei, p. 6.). Politisches Archiv des Auswartigen Amtes,  Bonn, Turkei 183, Armenien, Bd. 41. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.45)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR46.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR46.jpg"; Caption = "Whoever survived the agonies of the deportation marches came to the semi-desert and desert regions of northern Syria and Iraq. Contemporary European and American literature referred to the refugee camps along the Baghdad rail line as concentration camps. There were no preparations for the reception, let alone settlement of the Armenians. Wagner’s pictures show how the Armenians tried to protect themselves from the heat with primitive tents, awnings, or pieces of clothing. As the pictures further verify, the deportees were almost exclusively the elderly, women, and children. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.46)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR47.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR47.jpg"; Caption = "Whoever survived the agonies of the deportation marches came to the semi-desert and desert regions of northern Syria and Iraq. Contemporary European and American literature referred to the refugee camps along the Baghdad rail line as concentration camps. There were no preparations for the reception, let alone settlement of the Armenians. Wagner’s pictures show how the Armenians tried to protect themselves from the heat with primitive tents, awnings, or pieces of clothing. As the pictures further verify, the deportees were almost exclusively the elderly, women, and children. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.47)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR48.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR48.jpg"; Caption = "Whoever survived the agonies of the deportation marches came to the semi-desert and desert regions of northern Syria and Iraq. Contemporary European and American literature referred to the refugee camps along the Baghdad rail line as concentration camps. There were no preparations for the reception, let alone settlement of the Armenians. Wagner’s pictures show how the Armenians tried to protect themselves from the heat with primitive tents, awnings, or pieces of clothing. As the pictures further verify, the deportees were almost exclusively the elderly, women, and children. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.48)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR49.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR49.jpg"; Caption = "Whoever survived the agonies of the deportation marches came to the semi-desert and desert regions of northern Syria and Iraq. Contemporary European and American literature referred to the refugee camps along the Baghdad rail line as concentration camps. There were no preparations for the reception, let alone settlement of the Armenians. Wagner’s pictures show how the Armenians tried to protect themselves from the heat with primitive tents, awnings, or pieces of clothing. As the pictures further verify, the deportees were almost exclusively the elderly, women, and children. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.49)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR50.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR50.jpg"; Caption = "Whoever survived the agonies of the deportation marches came to the semi-desert and desert regions of northern Syria and Iraq. Contemporary European and American literature referred to the refugee camps along the Baghdad rail line as concentration camps. There were no preparations for the reception, let alone settlement of the Armenians. Wagner’s pictures show how the Armenians tried to protect themselves from the heat with primitive tents, awnings, or pieces of clothing. As the pictures further verify, the deportees were almost exclusively the elderly, women, and children. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.50)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR52.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR52.jpg"; Caption = "Whoever survived the agonies of the deportation marches came to the semi-desert and desert regions of northern Syria and Iraq. Contemporary European and American literature referred to the refugee camps along the Baghdad rail line as concentration camps. There were no preparations for the reception, let alone settlement of the Armenians. Wagner’s pictures show how the Armenians tried to protect themselves from the heat with primitive tents, awnings, or pieces of clothing. As the pictures further verify, the deportees were almost exclusively the elderly, women, and children. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.52)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR53.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR53.jpg"; Caption = "Mesopotamia 1915: Deported Armenian women doing wash in the Euphrates Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.53)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR54.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR54.jpg"; Caption = "Epidemics and vermin tormented the deportees in Mesopotamia. This photograph shows an Armenian child whose relatives are attempting to remove head lice. Left, the photographer’s shadow. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.54)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR55.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR55.jpg"; Caption = "\"This group of human wreckage represents tens of thousands when first approached with aid” James L. Barton, STORY OF NEAR EAST  RELIEF, 1915-1930 (New York: Macmillan, 1930). (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.55)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR56.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR56.jpg"; Caption = "Children taken in by Near East Relieft. This picture appeared in the diary of Maria Jacobsen, published in Beirut; it carried the note, in Danish: “Armenian children 1915-1918”. From the archive of Near East Relief in  Jacobsen, DIARY 1907-1919, KHARPUT, TURKEY. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.56)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR57.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR57.jpg"; Caption = "A living skeleton. A Near East Relief nurse examines an Armenian child. James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930). (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.57)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR58.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR58.jpg"; Caption = "Kharberd 1915: one of the numerous Armenian children wasted away to a skeleton Jacobsen, DIARY 1907-1919, KHARPUT, TURKEY. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.58)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR59.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR59.jpg"; Caption = "Starved Armenian woman with two small children Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.59)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR60.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR60.jpg"; Caption = "Armenian hunger victims Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.60)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR61.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR61.jpg"; Caption = "Dead of exhaustion: a deported Armenian child (Kharberd, 1915) Jacobsen, DIARY 1907-1919, KHARPUT, TURKEY. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.61)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR69.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR69.jpg"; Caption = "The Burning of Smyrna, September 14, 1922.  When Turkish-Kemalist troops captured the port city, populated predominantly by Greeks, they set the Christian quarter on fire. Approximately one hundred thousand people were massacred, burned, or died in the attempt to save themselves by swimming. There were ten thousand Armenians among them. Some of them had lived in Smyrna, while others had sought refuge there. The photograph was taken a day after the fire was set and shows the harbor quarter. James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930) (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.69)" }
  { Category = "Theme 10"; Filename = "AR70.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR70.jpg"; Caption = "Armenian and Greek children from orphanages in inland Asia Minor waiting in Constantinople for passage by ship to Greece. The Greek population of Asia Minor was deported there in accordance with the Lausanne treaty of 1923. James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930) (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.70)" }
  { Category = "Theme 10"; Filename = "AR71.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR71.jpg"; Caption = "Refugee camps in Port Said In September 1916. The allies evacuated over four thousand Armenians to Port Said from the six villages on Musa Ler (Sanjak of Alexandretta; Turkish: Hatay). When Cilicia and the sanjak came under French jurisdiction in 1919, the French encouraged the Armenians to return to their homeland. But in 1939 France withdrew permanently from the sanjak, and the residents of Musa Ler had to leave their home for a second and final time. The photograph shows Armenian refugee children in Port Said, getting their daily bread ration with discipline and patience. James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930) (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.71)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR72.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR72.jpg"; Caption = "The corpses of roughly 270 Armenian refugees from Karaklis being buried. They had been massacred by Azerbaijanis near the German colony of Katharinenfeld on June 1, 1918. The photograph is an enclosure to the six-page report of Lieutenant Walker, dated June 14, 1918 from Tiflis. Walker was an eyewitness to the massacre near Katharinenfeld. The originals of his report and photographs are in the Political Archive of the Foreign Office in Bonn (Turkei 183, Bd. 53). Politisches Archiv des Auswartigen Amtes, Bonn, Turkei 183, Bd. 53. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.72)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR73.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR73.jpg"; Caption = "The Turkish invasion of Transcaucasia in 1918 and 1920 released a new flood of refugees. The photograph shows Armenians from Alexandropol (renamed Leninakan: since 1990, Kumairi) fleeing the Turkish army. James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930)  (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.73)" }
  { Category = "Theme 10"; Filename = "AR74.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR74.jpg"; Caption = "At every railroad station of the Transcaucasus the workers of Near East Relief came upon starving Armenian children. Barton, STORY OF NEAR EAST RELIEF. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.74)" }
  { Category = "Theme 10"; Filename = "AR75.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR75.jpg"; Caption = "Homeless boy in Yerevan Near East archive document no. 266; published in Jacobsen, DIARY 1907-1919, KHARPUT, TURKEY. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.75)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR76.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR76.jpg"; Caption = "Refugee woman from Western Armenia in the streets of Yerevan in 1922 ALBUM HEIMATLAND (Yerevan, Paris. n.d.). (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.76)" }
  { Category = "Theme 10"; Filename = "AR80.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR80.jpg"; Caption = "“Children waiting in the snow for admission into the ‘Orphan City’, a daily spectacle from the early morning until late at night” James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930)  (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.80)" }
  { Category = "Theme 10"; Filename = "AR81.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR81.jpg"; Caption = "“Clamoring for admittance” Near East Relief in in Jacobsen, DIARY 1907-1919, KHARPUT, TURKEY. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.81)" }
  { Category = "Theme 10"; Filename = "AR82.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR82.jpg"; Caption = "“Two ragged waifs receive a ration of clothing from Near East Relief” James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930) (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.82)" }
  { Category = "Theme 10"; Filename = "AR84.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR84.jpg"; Caption = "“An assembly on the playground of the 30.000 population of the ‘Orphan City’ at Alexandropol, Armenia” Group photographs like this one and the following were directed at the charitability of American readers, for whom the efficiency of the relief operation was to be quantitatively demonstrated. Further, such photographs illustrate the large-scale misery in Eastern Armenia caused by the uprooting and expulsion of hundreds of thousands of Armenians. Barton, STORY OF NEAR EAST RELIEF. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.84)" }
  { Category = "Theme 10"; Filename = "AR85.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR85.jpg"; Caption = "“Alexandropol: ‘Hands up’, Polygon orphanage massed drill, October, 1925” The American educators placed a strong emphasis on the hygiene and physical training of their pupils. James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930)  (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.85)" }
  { Category = "Theme 10"; Filename = "AR86.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR86.jpg"; Caption = "“Section of a disease prevention camp for 30.000 children in the Caucasus” James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930)  (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.86)" }
  { Category = "Theme 10"; Filename = "AR89.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR89.jpg"; Caption = "Spiritual shepherd to a nation of orphans and refugees: Catholicos Gevork V receiving Armenian children James L. Barton, STORY OF NEAR EAST RELIFF. 1915-1930 (New York: Macmillan, 1930)  (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.89)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR91.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR91.jpg"; Caption = "Various Muslim peoples-Kurds, Bedouins-took in Armenian women and children and saved them from annihilation. Their motives were not always unselfish. The “adopted” Armenians had to take on their rescuers’ Islamic faith and work for them for free; often they were sexually abused. There were however cases of true generosity and humaneness. Among these were the islamicized Armenians of northern Syria who were taken in as children by Bedouins and later, out of thankfulness and conviction, maintained the faith and way of life of their adoptive families. They and their descendants do however still preserve the memory of their Armenian ancestry. These images come from an Alsatian missionary brochure. They portray the fate of an Armenian boy separated from his mother during the deportation and later taken in by Bedouins. At the end of his Odyssey he was reunited with his mother in America. Hedwig Bull, KARNIKS ABENTEUER IN MESOPOTAMEN: EINE WANRE GESCHICHTE (Kleine Orienthefte fur Jung Und Alt 3) (Strasbourg: Editions Oberlin,  No date (sometime after 1922)). (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.91)" }
  { Category = "Theme 10"; Filename = "AR95.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR95.jpg"; Caption = "Armenian widows and their children Benedictsen, ARMENIEN ET FOLKS LIV OG KAMP GENNEM TO AARTUSINDER. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.95)" }
  { Category = "Theme 10"; Filename = "AR99.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR99.jpg"; Caption = "Jakob Kunzler (1871-1949) Swiss-German surgeon active from 1899 to 1919 in the hospital of the German Orient Mission in Urfa; eyewitness to the Genocide of 1915-16. In the summer of 1922, he evacuated eight thousand Armenian children to Syria on behalf of Near East Relief, and subsequently looked after 1.400 orphan girls in Lebanon. The photograph shows Kunzler in an Armenian refugee camp in Beirut. Ida Alamuddin, PAPA KUNZLER AND THE  ARMENIANS (London, 1970). (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.99)" }
  { Category = "Theme 100000"; Filename = "AR102.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR102.jpg"; Caption = "Dr. Armin Theophil Wegner (1886-1978)  German writer. As member of the German-Ottoman Sanitation Mission as of autumn 1915, he was active for a year in Mesopotamia; eyewitnees to the deportations, which he documented in photographs. He addressed United States President Woodrow Wilson with an open letter on the occasion of the Paris Peace Conference (published February 1, 1919), in which he called for a free and internationally protected Armenian state of Eastern and Western Armenia as well as Cilicia. The photograph shows Wegner as second lieutenant in the German-Ottoman Sanitation Mission. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.102)" }
  { Category = "Theme 100000"; Filename = "AR103.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR103.jpg"; Caption = "Wegner in 1933, after he had been denounced, arrested, and tortured for his pacifist activist He was detained for several months in various German prisons and concentration camps. Armin T. Wegner collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.103)" }
  { Category = "Theme 100000"; Filename = "AR104.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR104.jpg"; Caption = "Wegner with Gerayer Koutcharian in 1969 in Geneva, where Wegner took part in an international Armenian convention as an honored guest. Gerayer Koutcharian Collection. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.104)" }
  { Category = "Theme 100000"; Filename = "AR105.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR105.jpg"; Caption = "Dr. Martin Niepage (1886-1963). Teacher in the German high school in Aleppo from 1913 to 1916; eyewitness to the Genocide; submitted a report to the German Parliament on October 15, 1915. An expanded version appeared as a brochure in 1916. Niepage avoided being arrested by Jemal Pasha in 1916 by returning to Germany in June of that year. SCHWEIZERISCE ORIENT-MISSION 2. Jg.,  Mai 1917, Nr. 5. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.105)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR107.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR107.jpg"; Caption = "In the morally strict societies of the East, one would only leave the dead of a marginalized, despised, and persecuted group to lie in such a degrading state of nudity. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.107)" }
  { Category = "Theme 10000"; Filename = "AR109.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR109.jpg"; Caption = "“The Trench Dug for the Bodies of the Victims: A Scene in the Cemetery. This photograph shows the horrible spectacle presented  to the visitors to the Armenian cemetery two days after the massacre. Two rows of dead, thirty-five deep, had already been laid down and partially covered with earth by labourers. When the photograph was taken, four men had just deposited another corpse, and so started a third row. The open spaces between the bodies were filled up with the skulls, thigh-bones, and other human remains from the graves disturbed by digging a huge grave fifty-three feet square for the reception of the slaughtered Armenians”. Photographs were published in 1895, in the illustrated British journal The Graphic, along with other photographs and drawings on the massacre of October 30, 1895, in Erzurum. A few photographs of the illustrated report carry the name Meisenbach in the lower left hand corner, from which one may conclude that the photographer or the photographic operation was German. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.109)" }
  { Category = "Theme 10000"; Filename = "AR110.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR110.jpg"; Caption = "“A Grim Corner of the Cemetery. Nothing could be more convincing as to the truth of the reports of massacres than the sight of corpses laid out in the cemetery waiting until one huge common grave had been dug for their reception”. Photographs were published in 1895, in the illustrated British journal The Graphic, along with other photographs and drawings on the massacre of October 30, 1895, in Erzurum. A few photographs of the illustrated report carry the name Meisenbach in the lower left hand corner, from which one may conclude that the photographer or the photographic operation was German. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.109)" }
  { Category = "The Armenian Genocide, 1915 – 1923"; Filename = "AR111.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR111.jpg"; Caption = "“Some of the Armenians who were killed and brought to the Armenian Relief Hospital, during the massacre of Feb. 28th, 1919, at Aleppo. Phot. Najarian Bros.” The photograph shows some of the victims, who according to handwritten captions were laid out in front of the “Armenian Relief Hospital” (American Relief Hospital?). Armenpress. (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.111)" }
  { Category = "Theme 10"; Filename = "AR114.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR114.jpg"; Caption = "The evacuation of eight thousand Armenian orphans to Syria by Jakob Kunzler on behalf of Near East Relief. Alamuddin, PAPA KUNZLER AND  THE ARMENIANS.  (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.114)" }
  { Category = "Theme 10"; Filename = "AR115.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/AR115.jpg"; Caption = "The evacuation of eight thousand Armenian orphans to Syria by Jakob Kunzler on behalf of Near East Relief. Alamuddin, PAPA KUNZLER AND  THE ARMENIANS (Tessa Hofmann and Gerayer Koutcharian, Images that Horrify and Indict: Pictorial Documents on the Persecution and Extermination of the Armenians from 1877 to 1922, Armenian Review, Spring/Summer 1992, Vol.45, fig.115)" }
