  { Category = "Theme 100000"; Filename = "Morgen01.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen01.jpg"; Caption = "Henry Morgenthau, American Ambassador at Constantinople from 1913 to 1916 Garden City New York Doubleday, Page and Company, 1918" }
  { Category = "Theme 1000000"; Filename = "Morgen07.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen07.jpg"; Caption = "TALAAT PASHA, GRAND VIZIER OF TURKEY. In 1914, when the war broke out, Talaat was Minister of the Interior and the most influential leader in the Committee of Union and Progress, the secret organization which controlled the Turkish Empire. A few years before Talaat was a letter-carrier, and afterward a telegraph operator in Adrianople. His talents are those of a great political boss. He represented Turkey in the peace negotiations with Russia and his signature appears on the Brest-Litovsk treaty." }
  { Category = "Theme 1000000"; Filename = "Morgen08a.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen08a.jpg"; Caption = "TURKISH INFANTRY AND CAVALRY. In January, 1914, the Turkish Army was a ragged, undisciplined force. These troops, drilled by German military instructors, show the result of six months' training" }
  { Category = "Theme 1000000"; Filename = "Morgen08b.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen08b.jpg"; Caption = "TURKISH INFANTRY AND CAVALRY. In January, 1914, the Turkish Army was a ragged, undisciplined force. These troops, drilled by German military instructors, show the result of six months' training" }
  { Category = "Theme 1000000"; Filename = "Morgen15.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen15.jpg"; Caption = "DJEMAL PASHA, MINISTER OF MARINE. In 1914 DjemaI headed the Police Department; it was his duty to run down citizens who were opposing the political gang then controlling Turkey. Such opponents were commonly assassinated or judicially murdered. Afterward Djemal was Minister of Marine, and as such violently protested against the sale of American warships to Greece. Then he was sent to Palestine as Commander of the Fourth Army Corps, where he distinguished himself as leader in the wholesale persecutions of the non-Moslem population." }
  { Category = "Theme 1000000"; Filename = "Morgen19.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen19.jpg"; Caption = "ENVER PASHA, MINISTER OF WAR. A man of the people, who, at 26, was a leader in the revolution which deposed Abdul Hamid and established the new regime of the Young Turks. At that time the Young Turks honestly desired to establish a Turkish democracy. This attempt failed miserably and the Young Turk leaders then ruled the Turkish Empire for their own selfish purposes, and developed a government which was much more wicked and murderous than that of Abdul Hamid. Enver was the man chiefly responsible for turning the Turkish army over to Germany. He imagined himself a Turkish combination of Napoleon and Frederick the Great." }
  { Category = "Theme 1000000"; Filename = "Morgen23.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen23.jpg"; Caption = "GERMAN AND TURKISH OFFICERS ON BOARD THE \"GOEBEN \". All the men, except the ones at the extreme left and extreme right, are Germans. Two months before Turkey entered the European war, Admiral Souchon---the central figure in this group---controlled the Turkish navy. All this time the German Government maintained that it had \"sold\" the Goeben and the Breslau to Turkey" }
  { Category = "Theme 1000000"; Filename = "Morgen24.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen24.jpg"; Caption = "BEDRI BEY, PREFECT OF POLICE AT CONSTANTINOPLE/ A leader of the Young Turks and an intimate friend of Talaat. Mr. Morgenthau's attempts to protect the English and French became a contest between himself and Bedri, who accepted the German view that foreigners should not be treated with \"too great leniency\"" }
  { Category = "Theme 1000000"; Filename = "Morgen24_2.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen24_2.jpg"; Caption = "DJAVID BEY, MINISTER OF FINANCE IN TURKISH CABINET. A Jew by race but a Mohammedan by religion; an influential member of the Young Turk party. He was Pro-Ally in his sympathies, and resigned when Turkey entered the war on Germany's side, though afterward he resumed office." }
  { Category = "Theme 1000000"; Filename = "Morgen31.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen31.jpg"; Caption = "HALIL BEY IN BERLIN. President of the Turkish Parliament and a leader of the Young Turks-afterward Minister for Foreign Affairs" }
  { Category = "Theme 1000000"; Filename = "Morgen34.jpg"; Url = "https://pub-08eca9699d664ab7b8f0d1fa87b15515.r2.dev/genocide/photos/normal/Morgen34.jpg"; Caption = "ENVER PASHA. \"I shall go down in history,\" this Turkish leader told Mr. Morgenthau, as the man who demonstrated the vulnerability of England and her fleet. I shall show that her navy is not invincible\"" }
